  "alibaba/wan-3.0-prime/text-to-video",
  {
    input: {
      "prompt": "A cinematic scene at sunset",
      "duration": 5,
      "resolution": "1080p",
      "aspect_ratio": "adaptive",
      "generate_audio": true,
      "enable_thinking": false
    },
    withPolling: true,
  },
);

console.log(result);
```

